package com.eventhub.service;
import com.eventhub.dto.*;import com.eventhub.entity.*;import com.eventhub.repository.*;import com.eventhub.util.TicketSecurity;import lombok.RequiredArgsConstructor;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @RequiredArgsConstructor public class AttendanceService{private final TicketRepository tickets;private final RegistrationRepository registrations;private final AttendanceRepository attendance;private final EventRepository events;private final UserRepository users; private final NotificationService notifications; private final AuditLogService audit;@Value("${app.jwt.secret}") private String ticketSecret;
@Transactional public AttendanceResponse checkIn(String email,String payload){User staff=users.findByEmailIgnoreCase(email).orElseThrow(()->new IllegalArgumentException("User not found"));if(!(staff.getRole()==Role.EVENT_STAFF||staff.getRole()==Role.ADMIN||staff.getRole()==Role.SUPER_ADMIN))throw new org.springframework.security.access.AccessDeniedException("Only event staff can check in attendees");String prefix="EVENTHUB:TICKET:";if(payload==null||!payload.startsWith(prefix))throw new IllegalArgumentException("INVALID TICKET");String[] p=payload.split(":");if(p.length!=4)throw new IllegalArgumentException("INVALID TICKET");Ticket t=tickets.findByTicketId(p[2]).orElseThrow(()->new IllegalArgumentException("INVALID TICKET"));String expected=TicketSecurity.hmac(t.getTicketId(),ticketSecret);if(!TicketSecurity.safeEquals(expected,p[3])||!TicketSecurity.safeEquals(t.getSecureTokenHash(),p[3]))throw new IllegalArgumentException("INVALID TICKET");Registration r=t.getRegistration();if(r.getStatus()!=RegistrationStatus.REGISTERED)throw new IllegalArgumentException("Ticket is not active");if(r.getEvent().getStatus()!=EventStatus.ONGOING)throw new IllegalArgumentException("Check-in is only available while the event is ongoing");if(attendance.existsByRegistrationId(r.getId()))throw new IllegalArgumentException("ALREADY CHECKED IN");Attendance a=attendance.save(Attendance.builder().registration(r).event(r.getEvent()).checkedInBy(staff).status(AttendanceStatus.CHECKED_IN).build());r.setStatus(RegistrationStatus.ATTENDED); notifications.send(r.getUser(),"Attendance confirmed","You have been checked in to "+r.getEvent().getTitle()+".",NotificationType.ATTENDANCE); audit.log(staff,"QR_CHECK_IN","REGISTRATION",r.getId(),null,"Attendance checked in");registrations.save(r);return AttendanceResponse.from(a);}
@Transactional(readOnly=true) public AttendanceStatsResponse stats(String email,Long eventId){Event e=events.findById(eventId).orElseThrow(()->new IllegalArgumentException("Event not found"));User u=users.findByEmailIgnoreCase(email).orElseThrow(()->new IllegalArgumentException("User not found"));if(!(u.getRole()==Role.EVENT_STAFF||u.getRole()==Role.ADMIN||u.getRole()==Role.SUPER_ADMIN||u.getRole()==Role.ORGANIZER&&e.getOrganizer().getId().equals(u.getId())))throw new org.springframework.security.access.AccessDeniedException("Not authorized");long reg=registrations.countByEventIdAndStatusIn(eventId,List.of(RegistrationStatus.REGISTERED,RegistrationStatus.ATTENDED));long checked=attendance.countByEventId(eventId);return new AttendanceStatsResponse(reg,checked,Math.max(0,reg-checked),reg==0?0:(checked*100.0/reg));}}
